<script setup lang="ts">import {ref,computed} from 'vue';import {Search,UsersRound,ArrowRight,Download} from 'lucide-vue-next';import WorkshopHeader from '../../components/WorkshopHeader.vue';import {customers} from '../../data/company';const search=ref('');const segment=ref('All customers');const segments=['All customers','Active','Dormant','High-value','Service due soon','Tyre customer','Open recommendations'];const shown=computed(()=>customers.filter(c=>(segment.value==='All customers'||c.segments.includes(segment.value))&&`${c.name} ${c.email} ${c.vehicles.join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
</script>
<template><WorkshopHeader title="Customers" subtitle="Shared across 2 locations"><button class="btn-secondary !min-h-10"><Download :size="16"/>Export</button></WorkshopHeader><div class="mx-auto max-w-[1400px] p-5 md:p-8"><div class="grid gap-3 md:grid-cols-[1fr_220px]"><label class="relative"><Search :size="18" class="absolute left-4 top-3.5 text-muted"/><input v-model="search" class="field pl-11" placeholder="Search name, email or vehicle"/></label><select v-model="segment" class="field"><option v-for="s in segments">{{s}}</option></select></div><div class="mt-6 overflow-hidden rounded-2xl border bg-white"><div class="hidden grid-cols-[1.2fr_1fr_100px_120px_130px_40px] gap-4 border-b bg-stone-50 px-5 py-3 text-xs font-semibold text-muted lg:grid"><span>Customer</span><span>Vehicles</span><span>Visits</span><span>Revenue</span><span>Next visit</span><span/></div><RouterLink v-for="c in shown" :to="`/workshop/customers/${c.id}`" class="grid gap-3 border-b p-5 last:border-0 hover:bg-stone-50 lg:grid-cols-[1.2fr_1fr_100px_120px_130px_40px] lg:items-center lg:gap-4"><span><strong class="block text-sm">{{c.name}}</strong><small class="text-muted">{{c.email}}</small></span><span class="text-sm">{{c.vehicles.join(', ')}}</span><span class="nums text-sm">{{c.visits}}</span><span class="nums text-sm font-semibold">€{{c.revenue.toLocaleString()}}</span><span class="text-sm" :class="c.nextVisit==='Overdue'?'text-red-700':'text-muted'">{{c.nextVisit}}</span><ArrowRight :size="17" class="text-muted"/></RouterLink></div></div></template>
